// Before: two carries + output selection
wire [N-1:0] sum_a = a + b;
wire [N-1:0] sum_b = c + d;
assign result = select ? sum_a : sum_b;

// After: input mux + one carry
wire [N-1:0] a_sel = select ? a : c;
wire [N-1:0] b_sel = select ? b : d;
assign result = a_sel + b_sel;

